	"dataSources": {
		"ds_2ZEIsGIq": {
			"name": "SingleValue - Total Regions",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats dc(RegionName)"
			},
			"type": "ds.chain"
		},
		"ds_4k6L34bX": {
			"name": "Donat - Total Effective Cost by Region",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats sum(sumEffectiveCost) AS TotalEffectiveCost by RegionName"
			},
			"type": "ds.chain"
		},
		"ds_6n9PEFwi_ds_uutPeUtF_ds_CRhx1DMK": {
			"name": "Column - Billed Cost per Service Category",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1mon eval(round(sum(sumBilledCost),2)) as EC by ServiceCategory \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_CRhx1DMK": {
			"name": "Column - Effective Cost per Service",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1mon eval(round(sum(sumEffectiveCost),2)) as EC by ServiceName \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_CmjVOqVP": {
			"name": "Column - Daily Effictive Cost per Service",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1d eval(round(sum(sumEffectiveCost),2)) AS TotalEffectiveCost BY ServiceName \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_DwalrReT_ds_4k6L34bX": {
			"name": "Donut - Total Billed Cost by Region",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats sum(sumBilledCost) AS TotalBilledCost by RegionName"
			},
			"type": "ds.chain"
		},
		"ds_IbywZQ53": {
			"name": "SingleValue - Total Sub Accounts",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats dc(SubAccountName)"
			},
			"type": "ds.chain"
		},
		"ds_Ozq5KyUv_ds_CmjVOqVP": {
			"name": "Column - Daily Billed Cost per Service",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1d eval(round(sum(sumBilledCost),2)) AS TotalBilledCost BY ServiceName \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_SQngzHwE_ds_urEjEMiB": {
			"name": "Column - Daily Billed Cost per Service Category",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1d eval(round(sum(sumBilledCost),2)) AS TotalBilledCost BY ServiceCategory \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_SUT81MKo": {
			"name": "SingleValue - Total Providers",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats dc(ProviderName)"
			},
			"type": "ds.chain"
		},
		"ds_SmMqVwnw_ds_z5Cbzqfi": {
			"name": "Bar - Billed Cost per Sub Account Name",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats sum(sumBilledCost) AS TotalBilledCost BY ServiceCategory SubAccountName \n| search TotalBilledCost > 2 \n| chart eval(round(sum(TotalBilledCost),2)) BY SubAccountName, ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_WUBAzfwL_ds_CRhx1DMK": {
			"name": "Column - Billed Cost per Service",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1mon eval(round(sum(sumBilledCost),2)) as EC by ServiceName \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_XYfY06QA": {
			"name": "Dropdown - Service Category",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| search ProviderName=\"$ProviderName$\" \n| dedup ServiceCategory \n| table ServiceCategory"
			},
			"type": "ds.chain"
		},
		"ds_YXJuTARQ": {
			"name": "BASE Search with Filter",
			"options": {
				"query": "| `focus_search`\nAND cost.ProviderName IN ($ProviderName|s$) \nAND cost.BillingAccountName IN ($BillingAccountName|s$) \nAND cost.ChargeCategory IN ($ChargeCategory|s$) \nAND cost.SubAccountName IN ($SubAccountName|s$) \nAND cost.ServiceCategory IN ($ServiceCategory|s$)\nAND cost.ServiceName IN ($ServiceName|s$) \n`focus_tstats_by`"
			},
			"type": "ds.search"
		},
		"ds_ZjZPzD1Q_ds_otOXgUWk": {
			"name": "SingleValue - Billed Costs",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| stats sum(BilledCost) AS BC \n| eval BC = round(BC,2)"
			},
			"type": "ds.chain"
		},
		"ds_aVdq1gNZ": {
			"name": "Dropdown - Service Name",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| search ProviderName=\"$ProviderName$\" ServiceCategory=\"$ServiceCategory$\"\n| dedup ServiceName \n| table ServiceName"
			},
			"type": "ds.chain"
		},
		"ds_aesSmc3G_ds_sD6Z76t6": {
			"name": "Column -Billed Cost per Provider",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "| timechart span=1mon eval(round(sum(sumBilledCost),2)) as EC by ProviderName \n| addtotals label=Total"
			},
			"type": "ds.chain"
		},
		"ds_lptDpZR1": {
			"name": "SingleValue - Potential Savings",
			"options": {
				"extend": "ds_YXJuTARQ",
				"query": "\n| stats sum(sumBilledCost) AS TotalBilledCost, sum(EffectiveCost) AS TotalEffectiveCost \n| eval Savings = round(TotalBilledCost - TotalEffectiveCost, 4) \n| eval SavingsPercentage = round((Savings / TotalBilledCost) * 100, 2) \n| table ServiceCategory, TotalBilledCost, TotalEffectiveCost, Savings, SavingsPercentage \n| eval SavingsPercentage = if(isnull(SavingsPercentage) OR SavingsPercentage <= 0, 0,SavingsPercentage) \n| table SavingsPercentage"
			},
			"type": "ds.chain"
		},
		"ds_otOXgUWk": {
			"name": "SingleValue - Effective Costs",
			"options": {
				"extend": "ds_YXJuTARQ",
